def build_thematic_health(existing_norms: set[str]):
    entries = []
    seen = set()
    rank = 1

    for row in HEALTH_ITEMS:
        kind = row[0]
        headword = row[1]
        param = row[2]
        level = row[3]
        msa = row[4]
        eg = row[5]
        domain = row[6]

        norm = norm_vocab(headword)
        if norm in existing_norms or norm in seen:
            continue
        seen.add(norm)

        if kind == "noun":
            gender = param if param in ("m", "f", "mf") else "m"
            art = "El" if gender == "m" else "La"
            ex_es = f"{art} {headword} es de suma importancia en el campo de la medicina."
            ex_ar = f"الـ{msa} ذو أهمية قصوى في مجال الطب."
            entry = make_noun(headword, gender, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        elif kind == "verb":
            paradigm = param or "ar"
            ex_es = f"Los médicos suelen {headword} para cuidar la salud del paciente."
            ex_ar = f"يعتاد الأطباء أن {msa} لرعاية صحة المريض."
            entry = make_verb(headword, paradigm, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        else:
            ex_es = f"Se diagnostica {headword} en las consultas hospitalarias."
            ex_ar = f"يُشخص {msa} في العيادات بالمستشفى."
            entry = make_adv(headword, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)

        entries.append(entry)
        rank += 1

    emit_bundle(
        filename="vocab-cv-topic-health.json",
        bundle_slug="cv-topic-health",
        title_ar="معجم مفردات الصحة والطب والتشريح والأدوية والطوارئ",
        entries=entries
    )
    return len(entries), seen

if __name__ == "__main__":
    count, _ = build_thematic_health(get_existing_norms())
    print(f"Generated {count} entries in vocab-cv-topic-health.json")
